import * as Auth from "$lib/API/Auth";
import { bindNativeMutationAuthority } from "$platform/mutation-authority";
import Mutex from "$lib/Mutex";
import { prefs } from "./prefs";
import { StatusCodes } from "http-status-codes";
import { get, writable } from "svelte/store";

const store = writable<CheckSessionResponse | undefined>();
bindNativeMutationAuthority(store);
const mutex = new Mutex();
let sessionGeneration = 0;
store.subscribe(() => { sessionGeneration++; });

const initialize = (force = false) =>
	mutex.wait(async () => {
		if (get(store) && !force) return;
		const generation = sessionGeneration;
		const res = await Auth.Check();
		if (generation !== sessionGeneration) return;
		if (res?.status === StatusCodes.OK && res.body?.identity?.id && res.body.identity.username) {
			store.set(res.body);
			const account = res.body.preferences;
			if (account) {
				const allowed = ["items_per_page", "languages", "show_safe", "show_suggestive", "show_erotic", "show_hentai", "tags", "translated_languages", "uploaders", "groups", "data_saver", "version"];
				const patch = Object.fromEntries(Object.entries(account).filter(([key]) => allowed.includes(key)));
				prefs.update(current => ({ ...current, ...patch }));
			}
		} else if (res?.status === StatusCodes.UNAUTHORIZED || res?.status === StatusCodes.FORBIDDEN || res?.status === StatusCodes.OK && !res.body?.identity?.id) {
			store.set(undefined);
		}
	});
initialize();

const isValid = () =>
	mutex.wait(() => {
		const session = get(store);
		return !!session?.identity?.id?.length && !!session?.identity?.username?.length;
	});

const hasPerm = (...perms: string[]) => {
	const session = get(store);
	if (!session) return false;
	return perms.some(perm => session.permissions?.includes(perm));
};

const hasRole = (...roles: string[]) => {
	const session = get(store);
	if (!session) return false;
	return roles.some(role => session.roles?.includes(role));
};

export default <
	typeof store & {
		initialize: typeof initialize;
		isValid: typeof isValid;
		hasPerm: typeof hasPerm;
		hasRole: typeof hasRole;
	}
>Object.assign(store, {
	initialize,
	isValid,
	hasPerm,
	hasRole
});
